import type { Metadata } from "next";
import type { ReactNode } from "react";

import { CodeBlock } from "@minanode/design-system/patterns/code-block";

import { DocsPage } from "@/components/docs/docs-page";
import { C, DocLink, DocSection, Prose } from "@/components/docs/prose";
import reference from "@/content/cli-reference.json";

// Generated by `mina internal cli-reference --format json`; a mina-cli test
// fails when the committed file differs from the binary's definitions.

type Arg =
  (typeof reference.commands)[number]["groups"][number]["args"][number];

export const metadata: Metadata = {
  title: "CLI reference",
  description:
    "Every mina command and option: its help, default and environment variable, generated from the binary.",
  alternates: { canonical: "/docs/cli/" },
};

/** Help text with `code` spans as inline code. */
function Text({ text }: { text: string }) {
  return (
    <>
      {text
        .split(/(`[^`]+`)/)
        .map((part, i) =>
          part.length > 2 && part.startsWith("`") && part.endsWith("`") ? (
            <C key={i}>{part.slice(1, -1)}</C>
          ) : (
            part
          ),
        )}
    </>
  );
}

function facts(arg: Arg) {
  const facts: ReactNode[] = [];
  if (arg.required) facts.push("Required.");
  if (arg.global) facts.push("Accepted by every command.");
  if (arg.aliases.length)
    facts.push(
      <>
        Alias:{" "}
        {arg.aliases.map((alias, i) => (
          <span key={alias}>
            {i ? ", " : null}
            <C>{alias}</C>
          </span>
        ))}
        .
      </>,
    );
  if (arg.default !== null)
    facts.push(
      <>
        Default: <C>{arg.default}</C>.
      </>,
    );
  if (arg.env !== null)
    facts.push(
      <>
        Environment: <C>{arg.env}</C>.
      </>,
    );
  return facts;
}

function Options({ args }: { args: Arg[] }) {
  return (
    <dl className="flex flex-col divide-y rounded-xl border bg-card">
      {args.map(arg => {
        const known = facts(arg);
        return (
          <div
            key={arg.id}
            id={arg.id}
            className="flex scroll-mt-24 flex-col gap-1.5 px-4 py-3"
          >
            <dt className="font-mono text-[0.8125rem] leading-6 font-medium break-words text-foreground">
              <a href={`#${arg.id}`} className="hover:underline">
                {arg.syntax}
              </a>
            </dt>
            <dd className="flex flex-col gap-1.5 text-sm leading-6 text-muted-foreground">
              {arg.help.map((paragraph, i) => (
                <p key={i}>
                  <Text text={paragraph} />
                </p>
              ))}
              {known.length ? (
                <p>
                  {known.map((fact, i) => (
                    <span key={i}>
                      {i ? " " : null}
                      {fact}
                    </span>
                  ))}
                </p>
              ) : null}
              {arg.possible_values.length ? (
                <ul className="flex list-disc flex-col gap-1 pl-5">
                  {arg.possible_values.map(value => (
                    <li key={value.name}>
                      <C>{value.name}</C>
                      {value.help ? (
                        <>
                          : <Text text={value.help} />
                        </>
                      ) : null}
                    </li>
                  ))}
                </ul>
              ) : null}
            </dd>
          </div>
        );
      })}
    </dl>
  );
}

// Notes the binary's help text doesn't carry yet.
const notes: Record<string, ReactNode> = {
  "wallet-generate": (
    <>
      It reads the new key&apos;s password from <C>MINA_PRIVKEY_PASS</C>, and
      stops if that is unset or empty.{" "}
      <DocLink href="/docs/block-producer/#key">The key</DocLink> shows how to
      set it.
    </>
  ),
};

export default function CliPage() {
  return (
    <DocsPage
      slug="cli"
      title="CLI reference"
      lead="Every command and option of the mina binary, generated from its definitions."
    >
      <Prose>
        <p>
          The same text is printed by <C>mina &lt;command&gt; --help</C>,
          apart from the notes this page adds to some commands. Every
          command also takes <C>-h</C> or <C>--help</C>, and <C>mina</C> itself
          takes <C>-V</C> or <C>--version</C>; they are not listed below. An
          option with an environment variable may be set by that variable
          instead; the option on the command line takes precedence. Before
          opening the HTTP port to other machines, read{" "}
          <DocLink href="/docs/dashboard/#on-a-server">
            viewing it on a server
          </DocLink>
          .
        </p>
        <ul>
          {reference.commands.map(command => (
            <li key={command.id}>
              <DocLink href={`#${command.id}`}>
                {["mina", ...command.path].join(" ")}
              </DocLink>
            </li>
          ))}
        </ul>
      </Prose>
      {reference.commands.map(command => (
        <DocSection
          key={command.id}
          id={command.id}
          title={<code>{["mina", ...command.path].join(" ")}</code>}
        >
          <Prose>
            {[command.about, ...command.details]
              .filter(Boolean)
              .map((paragraph, i) => (
                <p key={i}>
                  <Text text={paragraph} />
                </p>
              ))}
            {notes[command.id] ? <p>{notes[command.id]}</p> : null}
          </Prose>
          <CodeBlock code={command.usage} label="usage" />
          {command.subcommands.length ? (
            <Prose>
              <h3>Commands</h3>
              <ul>
                {command.subcommands.map(sub => (
                  <li key={sub.id}>
                    <DocLink href={`#${sub.id}`}>{sub.name}</DocLink>:{" "}
                    <Text text={sub.about} />
                  </li>
                ))}
              </ul>
            </Prose>
          ) : null}
          {command.groups.map(group => (
            <div key={group.title} className="flex flex-col gap-3">
              <h3 className="text-base font-semibold tracking-tight text-foreground">
                {group.title}
              </h3>
              <Options args={group.args} />
            </div>
          ))}
        </DocSection>
      ))}
    </DocsPage>
  );
}
